        elif cindy_hp <= 4:
            cindy_urgency += 0.15
        if cindy_nowater >= 1:
            cindy_urgency += 0.15
        if cindy_budget > budget * 1.5:
            cindy_urgency += 0.08

        if scarcity >= 0.7 or my_urgency >= 0.45:
